package main
import("context";"fmt";"os";"github.com/jackc/pgx/v5/pgxpool")
func main(){c:=context.Background();p,e:=pgxpool.New(c,os.Getenv("DATABASE_URL"));if e!=nil{panic(e)};defer p.Close();rows,e:=p.Query(c,`select r.id,r.end_at,r.next_fire_at,coalesce((select count(*) from generate_series((now() at time zone r.cron_timezone)::date,date '2026-09-09',interval '1 day') d where (r.active_weekdays&(1<<(extract(isodow from d)::int-1)))<>0 and ((d::date+r.daily_window_end) at time zone r.cron_timezone)>now() and ((d::date+r.daily_window_end) at time zone r.cron_timezone)<=r.end_at),0) future_windows from recordings r where r.account_id=47 and r.mode='continuous' and r.status='active' order by future_windows,r.id`);if e!=nil{panic(e)};defer rows.Close();n:=0;min:=999;for rows.Next(){var id int;var end,next any;var fw int;if e:=rows.Scan(&id,&end,&next,&fw);e!=nil{panic(e)};if fw<min{min=fw};fmt.Printf("RUNWAY %d windows=%d end=%v next=%v\n",id,fw,end,next);n++};fmt.Printf("RUNWAY_SUMMARY active=%d min_windows=%d\n",n,min)}
